mapper.select:
select a.*, at.name as typename, u1.username as pbraccount, u1.realname as pbrname
from activity a left join acttype at on at.id=a.typeid left join users u1 on u1.id=a.pubren
where 1=1
and a.title like '%${title}%'
and typeid=#{typeid}
and a.state=#{state}

select a.*, at.name as typename, u1.username as pbraccount, u1.realname as pbrname
from activity a left join acttype at on at.id=a.typeid left join users u1 on u1.id=a.pubren
where a.id=#{id}
